const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let inputIndex = 0;

function _read_ints() {
    return [parseInt(input[inputIndex++], 10), parseInt(input[inputIndex++], 10)];
}

const _A = 'a';
const _B = 'b';
const _C = 'c';

function main() {
    const [n, k] = _read_ints();
    const s = input[inputIndex++];
    const t = input[inputIndex++];
    const result = find_best_score_can_make(s, t, k);
    console.log(result.toString());
}

function find_best_score_can_make(s, t, moves_n) {
    if (t.length !== 2) throw new Error('assert len(t) == 2');
    if (t[0] === t[1]) {
        const t_char = t[0];
        let t_char_count = (s.match(new RegExp(t_char, 'g')) || []).length;
        t_char_count += moves_n;
        if (t_char_count > s.length) t_char_count = s.length;
        return (t_char_count * (t_char_count - 1)) / 2 | 0;
    }

    let mapped = [];
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === t[0] || char === t[1]) {
            mapped.push(([_A, _B])[t.indexOf(char)]);
        } else {
            mapped.push(_C);
        }
    }
    s = mapped.join('');

    const [a_indices, b_indices, c_indices] = _compute_abc_indices(s);

    let best_score = -Infinity;

    const max_c_start = Math.min(c_indices.length, moves_n);
    for (let c_start = 0; c_start <= max_c_start; c_start++) {
        const c_start_moves_spent = c_start;
        let moves_spent = c_start_moves_spent;
        let moves_remain = moves_n - moves_spent;
        if (moves_remain < 0) throw new Error('assert moves_remain >= 0');

        const max_b_start = Math.min(b_indices.length, moves_remain);
        for (let b_start = 0; b_start <= max_b_start; b_start++) {
            const b_start_moves_spent = b_start;
            moves_spent = c_start_moves_spent + b_start_moves_spent;
            moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new Error('assert moves_remain >= 0');

            const new_s = s.split('');
            for (let i_i_c = 0; i_i_c < c_start; i_i_c++) {
                const i_c = c_indices[i_i_c];
                new_s[i_c] = _A;
            }
            for (let i_i_b = 0; i_i_b < b_start; i_i_b++) {
                const i_b = b_indices[i_i_b];
                new_s[i_b] = _A;
            }

            const curr_best_score = _find_best_score_can_make_with_fixed_starts(new_s, moves_remain);
            if (curr_best_score > best_score) best_score = curr_best_score;
        }
    }

    return best_score;
}

function _compute_abc_indices(s) {
    const a_indices = [];
    const b_indices = [];
    const c_indices = [];
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === _A) {
            a_indices.push(i);
        } else if (char === _B) {
            b_indices.push(i);
        } else {
            if (char !== _C) throw new Error('assert char == _C');
            c_indices.push(i);
        }
    }
    return [a_indices, b_indices, c_indices];
}

function _find_best_score_can_make_with_fixed_starts(s, moves_n) {
    s = s.slice();

    let best_score = -Infinity;

    const [a_indices, b_indices, c_indices] = _compute_abc_indices(s.join(''));

    const a_n = a_indices.length;
    const c_n = c_indices.length;

    const max_a_stop = a_indices.length;
    const max_c_stop = c_indices.length;

    function get_c_stop_by_moves_remain(moves_remain) {
        let min_c_stop = max_c_stop - moves_remain;
        if (min_c_stop < 0) min_c_stop = 0;
        const c_stop = min_c_stop;
        return c_stop;
    }

    const first_c_stop = get_c_stop_by_moves_remain(moves_n);
    let new_s = _get_curr_s(s, a_indices, max_a_stop, c_indices, first_c_stop);
    let curr_score = _get_curr_score_slow_way(new_s);

    if (curr_score > best_score) best_score = curr_score;

    const old_a_before = _compute_a_before(new_s.join(''));
    const old_b_after_if_all_c_are_b = _compute_b_after(new_s.join('').replace(/c/g, _B));

    let curr_b_to_c_before_a = 0;
    let curr_a_to_b_after_c = 0;

    let prev_c_stop = null;
    let c_stop = first_c_stop;
    let c_stop_moves_spent = max_c_stop - c_stop;

    let min_a_stop = max_a_stop - moves_n;
    if (min_a_stop < 0) min_a_stop = 0;
    for (let a_stop = max_a_stop - 1; a_stop >= min_a_stop; a_stop--) {
        const a_stop_moves_spent = max_a_stop - a_stop;
        let moves_spent = a_stop_moves_spent;
        let moves_remain = moves_n - moves_spent;
        if (moves_remain < 0) throw new Error('assert moves_remain >= 0');

        const curr_a_index = a_indices[a_stop];
        const curr_b_to_c = c_stop;
        if (curr_b_to_c_before_a < curr_b_to_c &&
            c_indices[curr_b_to_c_before_a] < curr_a_index) {
            while (curr_b_to_c_before_a < curr_b_to_c &&
                   c_indices[curr_b_to_c_before_a] < curr_a_index) {
                curr_b_to_c_before_a += 1;
            }
        } else if (curr_b_to_c_before_a > 0 &&
                   c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
            while (curr_b_to_c_before_a > 0 &&
                   c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
                curr_b_to_c_before_a -= 1;
            }
        }

        const prev_a_stop_moves_spent = a_stop_moves_spent - 1;
        const curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a;
        const new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a;
        const b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after;
        curr_score -= b_after;
        curr_score += old_a_before[curr_a_index];

        prev_c_stop = c_stop;
        c_stop = get_c_stop_by_moves_remain(moves_remain);
        c_stop_moves_spent = max_c_stop - c_stop;

        if (!(c_stop - prev_c_stop === 0 || c_stop - prev_c_stop === 1)) {
            throw new Error('assert c_stop - prev_c_stop in (0, 1)');
        }
        if (c_stop - prev_c_stop === 1) {
            const prev_c_index = c_indices[prev_c_stop];
            const curr_a_to_b = a_n - a_stop;
            if (curr_a_to_b_after_c < curr_a_to_b &&
                a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                while (curr_a_to_b_after_c < curr_a_to_b &&
                       a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                    curr_a_to_b_after_c += 1;
                }
            } else if (curr_a_to_b_after_c > 0 &&
                       a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                while (curr_a_to_b_after_c > 0 &&
                       a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                    curr_a_to_b_after_c -= 1;
                }
            }

            const a_to_b_before = curr_a_to_b - curr_a_to_b_after_c;
            const curr_a_before = old_a_before[prev_c_index] - a_to_b_before;
            curr_score -= curr_a_before;
        }

        if (curr_score > best_score) best_score = curr_score;
    }

    return best_score;
}

function _get_curr_s(s, a_indices, a_stop, c_indices, c_stop) {
    const res = s.slice();
    for (let i_i_a = 0; i_i_a < a_stop; i_i_a++) {
        const i_a = a_indices[i_i_a];
        res[i_a] = _A;
    }
    for (let i_i_a = a_stop; i_i_a < a_indices.length; i_i_a++) {
        const i_a = a_indices[i_i_a];
        res[i_a] = _B;
    }
    for (let i_i_c = 0; i_i_c < c_stop; i_i_c++) {
        const i_c = c_indices[i_i_c];
        res[i_c] = _C;
    }
    for (let i_i_c = c_stop; i_i_c < c_indices.length; i_i_c++) {
        const i_c = c_indices[i_i_c];
        res[i_c] = _B;
    }
    return res;
}

function _get_curr_score_slow_way(s) {
    let curr_score = 0;
    let a_accumulated = 0;
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === _A) {
            a_accumulated += 1;
        } else if (char === _B) {
            curr_score += a_accumulated;
        }
    }
    return curr_score;
}

function _compute_a_before(s) {
    const result = new Array(s.length);
    let acc = 0;
    for (let i = 0; i < s.length; i++) {
        acc += (s[i] === _A ? 1 : 0);
        result[i] = acc;
    }
    const shifted = new Array(s.length + 1);
    shifted[0] = 0;
    for (let i = 0; i < s.length - 1; i++) {
        shifted[i + 1] = result[i];
    }
    return shifted;
}

function _compute_b_after(s) {
    const n = s.length;
    const result = new Array(n);
    let acc = 0;
    for (let i = n - 1; i >= 0; i--) {
        acc += (s[i] === _B ? 1 : 0);
        result[i] = acc;
    }
    const shifted = new Array(n);
    for (let i = 0; i < n - 1; i++) {
        shifted[i] = result[i + 1];
    }
    shifted[n - 1] = 0;
    return shifted;
}

