function _get_curr_score_slow_way(s) {
    let curr_score = 0;
    let a_accumulated = 0;
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === _A) {
            a_accumulated += 1;
        } else if (char === _B) {
            curr_score += a_accumulated;
        }
    }
