function _compute_a_before(s) {
    const res = new Array(s.length);
    let acc = 0;
    for (let i = 0; i < s.length; i++) {
        acc += (s[i] === _A ? 1 : 0);
        res[i] = acc;
    }
    const result = new Array(s.length + 1);
    result[0] = 0;
    for (let i = 0; i < s.length; i++) {
        result[i + 1] = res[i];
    }
    return result.slice(0, -1);
}

function _compute_b_after(s) {
    const n = s.length;
    const res = new Array(n);
    let acc = 0;
    for (let i = n - 1; i >= 0; i--) {
        acc += (s[i] === _B ? 1 : 0);
        res[i] = acc;
    }
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        result[i] = res[i];
    }
    const finalRes = new Array(n);
    for (let i = 0; i < n - 1; i++) {
        finalRes[i] = result[i + 1];
    }
    finalRes[n - 1] = 0;
    return finalRes;
}

